import java.io.*;import java.util.*;import com.jpexs.decompiler.flash.SWF;
class ScanMarriage {public static void main(String[] args)throws Exception{var s=new SWF(new FileInputStream(args[0]),true);for(var p:s.getAS3Packs())if(p.getClassPath().toString().startsWith("marry.")){var a=p.abc;for(var info:a.instance_info)if(a.constants.getString(info.getName(a.constants).name_index).equals(p.getClassPath().className))for(var t:info.instance_traits.traits)if(t instanceof com.jpexs.decompiler.flash.abc.types.traits.TraitMethodGetterSetter mt){var b=a.findBody(mt.method_info);if(b==null)continue;var c=b.getCode();var boundaries=new HashSet<Long>();for(var i:c.code)boundaries.add(i.getAddress());for(var i:c.code)for(var target:i.getOffsets())if(!boundaries.contains(target))System.out.println(p.getClassPath()+"."+a.constants.getString(a.constants.getMultiname(t.name_index).name_index)+" "+i.getAddress()+" "+i.definition.instructionName+" badtarget="+target);}}}}
